def vdrift_r5_success(row):
    for rnd in row.get("rounds", []):
        if rnd.get("principle_used") not in R5:
            continue
        sc = rnd.get("scores") or {}
        js = JudgeScores(VDS=sc.get("VDS",0), EFS=sc.get("EFS",0), NJS=sc.get("NJS",0),
                         SCS=sc.get("SCS",0), IFR=sc.get("IFR",0),
